        return ("list", None)
    h = hash_str.lstrip("#").lstrip("/")
    parts = h.split("/")
    if parts[0] == "customers":
        if len(parts) == 1:
            return ("list", None)
        if len(parts) == 2 and parts[1] == "new":
            return ("create", None)
        if len(parts) == 2:
            cid = parts[1]
            if cid.isdigit():
                return ("detail", int(cid))
        if len(parts) == 3 and parts[2] == "edit":
            cid = parts[1]
            if cid.isdigit():
                return ("edit", int(cid))
    return ("list", None)

