@component
def Sparkline(points, width, height):
    if len(points) < 2:
        return svg(width=width, height=height)()

    max_v = points[0].value
    min_v = points[0].value
    for p in points:
        if p.value > max_v:
            max_v = p.value
        if p.value < min_v:
            min_v = p.value

    span = max_v - min_v
    if span == 0:
        span = 1

    coords = []
    for i, p in enumerate(points):
        x = (i / (len(points) - 1)) * width
        y = height - ((p.value - min_v) / span) * height
        coords.append(f"{x:.1f},{y:.1f}")

    polyline_points = " ".join(coords)
    return svg(width=width, height=height)(polyline(points=polyline_points, stroke="#3b82f6", stroke_width=2, fill="none"))

